#!/bin/bash
# STN-41: lag-alert の案内文の時間は上限（6 時間）と一致する
fail=0
out=$(NOW=$(date -u -d 2026-11-04T00:00:00Z +%s) bash ops/lag-alert.sh)
echo "$out" | grep -q '最大 6 時間' || { echo "lag-alert message limit"; fail=1; }
echo "$out" | grep -q '24' && { echo "lag-alert stale 24"; fail=1; }
exit $fail

